// Channel block (WhatsApp today; swap here for SMS). Sends AND logs in Conversaciones.
// Bloque de canal (hoy WhatsApp; para SMS se cambia aquí). Envía Y registra en Conversaciones.
// Input: { lead_id, whatsapp, mensaje, origen ('P31'...), rol ('assistant'|'user'|'equipo'),
//          off_topic (bool), solo_registrar (bool: inbound or message we must not send), wa_message_sid (inbound) }
const TWILIO_FROM = 'whatsapp:YOUR_TWILIO_WHATSAPP_NUMBER'; // Twilio WhatsApp Sandbox
const i = $('When Called').first().json;
const txt = v => (v == null ? '' : String(v)).trim();
const yes = v => v === true || v === 'true';

const whatsapp = txt(i.whatsapp).replace(/^whatsapp:/, '');
const mensaje = txt(i.mensaje).slice(0, 1500); // WhatsApp corta en 1.600
const errores = [];
if (!/^\+\d{11,15}$/.test(whatsapp)) errores.push('whatsapp');
if (!mensaje) errores.push('mensaje');

const solo_registrar = yes(i.solo_registrar);
// Public n8n URL for Twilio's status callback ($env is blocked in Code nodes here)
// URL pública de n8n para el status callback ($env está bloqueado en los Code nodes)
const base = String($execution.resumeUrl || '').split('webhook-waiting')[0];

return [{ json: {
  lead_id: txt(i.lead_id),
  whatsapp,
  to: 'whatsapp:' + whatsapp,
  from: TWILIO_FROM,
  mensaje,
  origen: txt(i.origen) || 'P31',
  rol: txt(i.rol) || (solo_registrar ? 'user' : 'assistant'),
  off_topic: yes(i.off_topic),
  solo_registrar,
  wa_message_sid_in: txt(i.wa_message_sid),
  status_callback: base ? base + 'webhook/lumiere-wa-status' : '',
  errores,
  enviar: !solo_registrar && errores.length === 0
} }];

// One row for Conversaciones, whether it was sent, failed or only logged.
// Una fila para Conversaciones: enviado, fallido o solo registrado.
const m = $('Prepare Message').first().json;
const sent = $('Send via Twilio').isExecuted;
const r = sent ? ($('Send via Twilio').first().json || {}) : {};

let sid = m.wa_message_sid_in;
let estado_entrega = m.rol === 'user' ? 'recibido' : 'solo_registro';
let error = '';
if (!m.solo_registrar && m.errores.length) { estado_entrega = 'error'; error = 'invalid: ' + m.errores.join(','); }
if (sent) {
  if (r.sid) { sid = r.sid; estado_entrega = r.status || 'queued'; }
  else { estado_entrega = 'error'; error = String((r.error && (r.error.message || r.error.description)) || r.message || 'twilio_error').slice(0, 200); }
}

const fecha = $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
return [{ json: {
  row: [fecha, m.lead_id, m.whatsapp, m.rol, m.origen, m.mensaje, sid, error ? 'error: ' + error : estado_entrega, m.off_topic],
  ok: estado_entrega !== 'error',
  enviado: sent && Boolean(r.sid),
  wa_message_sid: sid,
  estado_entrega,
  error,
  fecha
} }];

// What the caller gets back / Lo que recibe el flujo que llamó
const b = $('Build Log Row').first().json;
return [{ json: { ok: b.ok, enviado: b.enviado, wa_message_sid: b.wa_message_sid, estado_entrega: b.estado_entrega, error: b.error, fecha: b.fecha } }];
